package main

import (
	"reflect"
	"testing"
)

func TestMergeSortedVerify(t *testing.T) {
	tests := []struct {
		a, b, want []int
	}{
		{[]int{1, 3, 5}, []int{2, 4, 6}, []int{1, 2, 3, 4, 5, 6}},
		{[]int{}, []int{1, 2}, []int{1, 2}},
		{[]int{1, 2}, []int{}, []int{1, 2}},
		{[]int{1, 1, 2}, []int{1, 3}, []int{1, 1, 1, 2, 3}},
		{[]int{-5, 0}, []int{-3, 4}, []int{-5, -3, 0, 4}},
	}
	for _, tt := range tests {
		got := mergeSorted(tt.a, tt.b)
		if !reflect.DeepEqual(got, tt.want) {
			t.Fatalf("mergeSorted(%v, %v) = %v, want %v", tt.a, tt.b, got, tt.want)
		}
	}
}

